ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(txt_Motivo_DSG_3.Text) && CountIf(
        datos_DSCN,
        !aprobado
    ) > 0,
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "Debe indicar el motivo del rechazo de los items"
            }
        }
    ),
    true,
    UpdateContext({Guardando: true});
    RemoveIf(
        Compras_NoMarcadas,
        NSolicitud = Soli && NFilaSolicitud in Filter(
            datos_DSCN,
            aprobado
        ).NFilaSolicitud && Tipo_Envio = "Compras"
    );
    With(
        {
            Consecutivo: CountIf(
                Solicitud_Compras,
                Soli in soli_num
            )
        },
        Collect(
            Solicitud_Compras,
            {
                soli_num: If(
                    Consecutivo = 0,
                    Upper(Soli),
                    Upper(Soli) & "-" & (Consecutivo + 1)
                ),
                fecha: DateValue(txt_Fecha_DSGN_2.Text),
                solicitante: txt_Solicitante_DSGN_2.Text,
                user: varEmpleado.Nombre,
                total: Value(
                    Sum(
                        Filter(
                            datos_DSCN,
                            aprobado
                        ),
                        subtotal
                    )
                ),
                estado: "Listo"
            }
        );
        ForAll(
            Filter(
                datos_DSCN,
                aprobado
            ),
            Collect(
                Detalle_Solicitud_Compras,
                {
                    soli_num: If(
                        Consecutivo = 0,
                        Upper(Soli),
                        Upper(Soli) & "-" & (Consecutivo + 1)
                    ),
                    item: ThisRecord.NItem,
                    descripcion: ThisRecord.Descripcion,
                    linea: ThisRecord.NFilaSolicitud
                }
            )
        );
    );
    Reset(txt_Num_Soli_DSGN_2);
    UpdateContext({showContainer: false});
    Reset(txt_Motivo_DSG_3);
    UpdateContext({Guardando: false});
    Clear(datos_DSCN);
    Back(),
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "La solicitud seleccionada ya fue enviada"
            }
        }
    )
);
